-- UTF-8. V191: material library, content review batches, and student-scoped partner invitations.
-- Migration-Owner: ai
-- Dependencies/order: apply after V185. This migration owns the material-library schema and metadata.
-- Data scope: additive ZSJOS schema, four confirmed material type rows per enabled tenant, two
-- administrator-maintained dictionary types, the nine confirmed profession options, menu metadata,
-- compatible legacy content-page grants, and schema-version records. BPM categories are
-- provisioned through BpmCategoryApi when the application initializes each tenant.
-- It does not seed material instances, review batches, invitations, or role identities. The default
-- viral-account schema is generated by MaterialTenantInitializer after application startup.
-- Repeatability: tables, columns, indexes, configuration rows, menus, packages, and markers are guarded.
-- Recovery: forward-only once material/content versions reference this schema; hide menus and retain data on rollback.

SET NAMES utf8mb4;

DROP PROCEDURE IF EXISTS `zsjos_v191_add_column`;
DELIMITER $$
CREATE PROCEDURE `zsjos_v191_add_column`(
  IN p_table varchar(64), IN p_column varchar(64), IN p_definition text
)
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema=DATABASE() AND table_name=p_table AND column_name=p_column
  ) THEN
    SET @zsjos_v191_ddl=CONCAT('ALTER TABLE `',p_table,'` ADD COLUMN `',p_column,'` ',p_definition);
    PREPARE zsjos_v191_stmt FROM @zsjos_v191_ddl;
    EXECUTE zsjos_v191_stmt;
    DEALLOCATE PREPARE zsjos_v191_stmt;
  END IF;
END$$
DELIMITER ;

DROP PROCEDURE IF EXISTS `zsjos_v191_add_index`;
DELIMITER $$
CREATE PROCEDURE `zsjos_v191_add_index`(
  IN p_table varchar(64), IN p_index varchar(64), IN p_definition text
)
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.statistics
    WHERE table_schema=DATABASE() AND table_name=p_table AND index_name=p_index
  ) THEN
    SET @zsjos_v191_ddl=CONCAT('ALTER TABLE `',p_table,'` ADD ',p_definition);
    PREPARE zsjos_v191_stmt FROM @zsjos_v191_ddl;
    EXECUTE zsjos_v191_stmt;
    DEALLOCATE PREPARE zsjos_v191_stmt;
  END IF;
END$$
DELIMITER ;

DROP PROCEDURE IF EXISTS `zsjos_v191_apply`;
DELIMITER $$
CREATE PROCEDURE `zsjos_v191_apply`()
BEGIN
  DECLARE v_menu_id int DEFAULT 80010;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  IF NOT EXISTS (SELECT 1 FROM `zsjos_schema_version` WHERE `version`='V185')
     OR NOT EXISTS (SELECT 1 FROM `zsjos_module_schema_version`
                    WHERE `module_code`='core' AND `version`='V185') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 requires V185 in both schema-version registries';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM `system_menu` WHERE `id`=6735 AND `deleted`=b'0') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 requires ZSJOS menu root 6735';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM `system_menu` WHERE `id`=7022 AND `deleted`=b'0') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 requires media student page 7022';
  END IF;
  IF EXISTS (
    SELECT 1 FROM `system_menu` menu_row WHERE menu_row.`id` BETWEEN 80010 AND 80040
      AND (menu_row.`type` <> CASE WHEN menu_row.`id`=80010 THEN 1
                                    WHEN menu_row.`id` BETWEEN 80011 AND 80015 OR menu_row.`id`=80040 THEN 2
                                    ELSE 3 END
        OR menu_row.`parent_id` <> CASE menu_row.`id`
             WHEN 80010 THEN 6735
             WHEN 80011 THEN 80010 WHEN 80012 THEN 80010 WHEN 80013 THEN 80010
             WHEN 80014 THEN 80010 WHEN 80015 THEN 80010
             WHEN 80016 THEN 80011 WHEN 80017 THEN 80011 WHEN 80018 THEN 80011
             WHEN 80019 THEN 80012 WHEN 80020 THEN 80012
             WHEN 80021 THEN 80011 WHEN 80022 THEN 80011 WHEN 80023 THEN 80011
             WHEN 80024 THEN 80013 WHEN 80025 THEN 80013 WHEN 80026 THEN 80013
             WHEN 80027 THEN 80013 WHEN 80028 THEN 80014 WHEN 80029 THEN 80014
             WHEN 80030 THEN 80014 WHEN 80031 THEN 80013
             WHEN 80032 THEN 80015 WHEN 80033 THEN 80015 WHEN 80034 THEN 80015
             WHEN 80035 THEN 80015 WHEN 80036 THEN 80015 WHEN 80037 THEN 7022
             WHEN 80038 THEN 80015 WHEN 80039 THEN 80014 WHEN 80040 THEN 80010 END
        OR COALESCE(menu_row.`permission`,'') <> CASE menu_row.`id`
             WHEN 80010 THEN '' WHEN 80011 THEN 'zsjos:material:query'
             WHEN 80012 THEN 'zsjos:material:manage' WHEN 80013 THEN 'zsjos:material-type:query'
             WHEN 80014 THEN 'zsjos:material-import:query' WHEN 80015 THEN 'zsjos:content-review:query'
             WHEN 80016 THEN 'zsjos:material:create' WHEN 80017 THEN 'zsjos:material:update'
             WHEN 80018 THEN 'zsjos:material:submit' WHEN 80019 THEN 'zsjos:material:disable'
             WHEN 80020 THEN 'zsjos:material:restore' WHEN 80021 THEN 'zsjos:material:like'
             WHEN 80022 THEN 'zsjos:material:favorite' WHEN 80023 THEN 'zsjos:material:reference'
             WHEN 80024 THEN 'zsjos:material-type:create' WHEN 80025 THEN 'zsjos:material-type:update'
             WHEN 80026 THEN 'zsjos:material-schema:update' WHEN 80027 THEN 'zsjos:material-schema:publish'
             WHEN 80028 THEN 'zsjos:material-import:download' WHEN 80029 THEN 'zsjos:material-import:preview'
             WHEN 80030 THEN 'zsjos:material-import:commit' WHEN 80031 THEN 'zsjos:content-review:config'
             WHEN 80032 THEN 'zsjos:content-review:create' WHEN 80033 THEN 'zsjos:content-review:submit'
             WHEN 80034 THEN 'zsjos:content-review:director-review'
             WHEN 80035 THEN 'zsjos:content-review:final-review'
             WHEN 80036 THEN 'zsjos:content-review:publish-register'
             WHEN 80037 THEN 'zsjos:partner-invitation:create-student'
             WHEN 80038 THEN 'zsjos:content-review:query-all'
             WHEN 80039 THEN 'zsjos:material-import:error-download'
             WHEN 80040 THEN 'zsjos:content:query' END
        OR COALESCE(menu_row.`path`,'') <> CASE menu_row.`id`
             WHEN 80010 THEN 'material-library' WHEN 80011 THEN 'browse' WHEN 80012 THEN 'manage'
             WHEN 80013 THEN 'types' WHEN 80014 THEN 'imports' WHEN 80015 THEN 'content-review'
             WHEN 80040 THEN 'content-production' ELSE '' END)
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 menu ID range is occupied';
  END IF;
  IF EXISTS (
    SELECT 1 FROM `system_menu` WHERE `id` NOT BETWEEN 80010 AND 80040 AND `deleted`=b'0'
      AND `permission` IN ('zsjos:material:query','zsjos:material:manage','zsjos:material-type:query',
        'zsjos:material-import:query','zsjos:content-review:query','zsjos:material:create',
        'zsjos:material:update','zsjos:material:submit','zsjos:material:disable','zsjos:material:restore',
        'zsjos:material:like','zsjos:material:favorite','zsjos:material:reference','zsjos:material-type:create',
        'zsjos:material-type:update','zsjos:material-schema:update','zsjos:material-schema:publish',
        'zsjos:material-import:download','zsjos:material-import:preview','zsjos:material-import:commit',
        'zsjos:content-review:config','zsjos:content-review:create','zsjos:content-review:submit',
        'zsjos:content-review:director-review','zsjos:content-review:final-review',
        'zsjos:content-review:publish-register','zsjos:partner-invitation:create-student',
        'zsjos:content-review:query-all','zsjos:material-import:error-download','zsjos:content:query')
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 permission is already owned by another menu';
  END IF;

  CREATE TABLE IF NOT EXISTS `zsjos_material_type` (
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '素材类型编号',
    `code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '稳定类型编码',
    `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '类型名称',
    `description` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '类型说明',
    `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态：0启用 1停用',
    `current_schema_version_id` bigint DEFAULT NULL COMMENT '当前已发布模板版本',
    `bpm_process_definition_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '素材审批流程定义 Key',
    `allow_manual_create` bit(1) NOT NULL DEFAULT b'1',
    `allow_import` bit(1) NOT NULL DEFAULT b'0',
    `allow_auto_collect` bit(1) NOT NULL DEFAULT b'0',
    `recommendation_enabled` bit(1) NOT NULL DEFAULT b'0',
    `recommendation_config_json` json DEFAULT NULL COMMENT '推荐规则配置',
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_type_code` (`tenant_id`,`code`,`deleted`),
    KEY `idx_material_type_status` (`tenant_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材类型';

  CREATE TABLE IF NOT EXISTS `zsjos_material_schema_version` (
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '素材模板版本编号',
    `material_type_id` bigint NOT NULL,
    `version_no` int NOT NULL,
    `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'draft/published/archived',
    `fields_json` json NOT NULL COMMENT '字段定义快照',
    `schema_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `published_by_user_id` bigint DEFAULT NULL,
    `published_at` datetime DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_schema_version` (`tenant_id`,`material_type_id`,`version_no`,`deleted`),
    KEY `idx_material_schema_status` (`tenant_id`,`material_type_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='不可变素材表单模板版本';

  CREATE TABLE IF NOT EXISTS `zsjos_material` (
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '素材编号',
    `material_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '素材业务编号',
    `material_type_id` bigint NOT NULL,
    `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '素材库标题',
    `cover_snapshot_json` json DEFAULT NULL,
    `summary` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `source` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'MANUAL/IMPORT/CONTENT_REVIEW',
    `source_business_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `source_business_version_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DRAFT/IN_APPROVAL/EFFECTIVE/REJECTED/DISABLED',
    `current_draft_version_id` bigint DEFAULT NULL,
    `current_effective_version_id` bigint DEFAULT NULL,
    `owner_user_id` bigint NOT NULL,
    `like_count` bigint NOT NULL DEFAULT 0,
    `favorite_count` bigint NOT NULL DEFAULT 0,
    `reference_count` bigint NOT NULL DEFAULT 0,
    `pinned` bit(1) NOT NULL DEFAULT b'0',
    `priority` int NOT NULL DEFAULT 0,
    `disabled_reason` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `disabled_at` datetime DEFAULT NULL,
    `disabled_by_user_id` bigint DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_no` (`tenant_id`,`material_no`,`deleted`),
    UNIQUE KEY `uk_material_source` (`tenant_id`,`material_type_id`,`source`,`source_business_id`,`source_business_version_id`,`deleted`),
    KEY `idx_material_list` (`tenant_id`,`material_type_id`,`status`,`pinned`,`priority`,`id`),
    KEY `idx_material_owner` (`tenant_id`,`owner_user_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材主记录';

  CREATE TABLE IF NOT EXISTS `zsjos_material_version` (
    `id` bigint NOT NULL AUTO_INCREMENT COMMENT '素材内容版本编号',
    `material_id` bigint NOT NULL,
    `version_no` int NOT NULL,
    `schema_version_id` bigint NOT NULL,
    `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DRAFT/IN_APPROVAL/EFFECTIVE/REJECTED',
    `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
    `cover_snapshot_json` json DEFAULT NULL,
    `summary` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `values_json` json NOT NULL,
    `field_snapshot_json` json NOT NULL,
    `dict_snapshot_json` json NOT NULL,
    `file_snapshot_json` json NOT NULL,
    `search_text` mediumtext COLLATE utf8mb4_unicode_ci,
    `content_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `process_definition_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `process_definition_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `process_definition_version` int DEFAULT NULL,
    `process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `business_key` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `submitted_by_user_id` bigint DEFAULT NULL,
    `submitted_at` datetime DEFAULT NULL,
    `effective_at` datetime DEFAULT NULL,
    `rejected_at` datetime DEFAULT NULL,
    `rejection_reason` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_content_version` (`tenant_id`,`material_id`,`version_no`,`deleted`),
    UNIQUE KEY `uk_material_process_instance` (`tenant_id`,`process_instance_id`),
    UNIQUE KEY `uk_material_business_key` (`tenant_id`,`business_key`),
    KEY `idx_material_version_state` (`tenant_id`,`material_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='不可变素材内容版本';

  CREATE TABLE IF NOT EXISTS `zsjos_material_dimension` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `material_version_id` bigint NOT NULL,
    `dimension_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'account_type/profession/account_stage',
