    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_dimension` (`tenant_id`,`material_version_id`,`dimension_key`,`dimension_value`,`deleted`),
    KEY `idx_material_dimension_match` (`tenant_id`,`dimension_key`,`dimension_value`,`material_version_id`)
