  CREATE TABLE IF NOT EXISTS `zsjos_material_field_index` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `material_version_id` bigint NOT NULL,
    `field_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `group_index` int NOT NULL DEFAULT -1 COMMENT '-1 表示非重复组字段',
    `value_code` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `label_snapshot` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `text_value` text COLLATE utf8mb4_unicode_ci,
