    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    KEY `idx_material_field_lookup` (`tenant_id`,`field_key`,`value_code`,`material_version_id`),
    KEY `idx_material_field_number` (`tenant_id`,`field_key`,`number_value`,`material_version_id`),
    KEY `idx_material_field_date` (`tenant_id`,`field_key`,`date_value`,`material_version_id`),
    KEY `idx_material_field_datetime` (`tenant_id`,`field_key`,`datetime_value`,`material_version_id`),
    KEY `idx_material_field_version` (`tenant_id`,`material_version_id`,`field_key`,`group_index`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材动态字段结构化索引';

