    UNIQUE KEY `uk_material_file_ref` (`tenant_id`,`material_version_id`,`field_key`,`group_index`,`infra_file_id`,`deleted`),
    KEY `idx_material_file_version` (`tenant_id`,`material_version_id`,`field_key`,`group_index`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材版本文件引用快照';

