  CREATE TABLE IF NOT EXISTS `zsjos_material_import_batch` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `batch_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `material_type_id` bigint NOT NULL,
    `schema_version_id` bigint NOT NULL,
    `source_file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
    `source_file_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `status` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PREVIEWED/COMMITTED',
    `total_count` int NOT NULL DEFAULT 0,
    `success_count` int NOT NULL DEFAULT 0,
    `failure_count` int NOT NULL DEFAULT 0,
    `preview_rows_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
    `idempotency_key` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
    `created_by_user_id` bigint NOT NULL,
    `confirmed_by_user_id` bigint DEFAULT NULL,
    `confirmed_at` datetime DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_material_import_no` (`tenant_id`,`batch_no`,`deleted`),
    UNIQUE KEY `uk_material_import_idempotency` (`tenant_id`,`idempotency_key`,`deleted`),
    KEY `idx_material_import_list` (`tenant_id`,`material_type_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材 Excel 导入批次';

  CREATE TABLE IF NOT EXISTS `zsjos_material_import_error` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `batch_id` bigint NOT NULL,
    `sheet_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
    `row_no` int NOT NULL,
    `field_key` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `error_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `error_message` varchar(1000) COLLATE utf8mb4_unicode_ci NOT NULL,
    `row_snapshot_json` json DEFAULT NULL,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    KEY `idx_material_import_error` (`tenant_id`,`batch_id`,`row_no`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='素材导入逐行错误';

  CREATE TABLE IF NOT EXISTS `zsjos_content_review_config` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `process_definition_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `director_task_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `final_task_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `production_material_type_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'production_content',
    `material_field_mapping_json` json DEFAULT NULL COMMENT '生产内容到动态素材字段的受控映射',
    `material_default_values_json` json DEFAULT NULL COMMENT '自动收录时的管理员默认字段值',
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    `active_tenant_id` bigint GENERATED ALWAYS AS (CASE WHEN `deleted`=b'0' THEN `tenant_id` ELSE NULL END) STORED,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_content_review_config_tenant` (`active_tenant_id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产内容批审配置';

  CREATE TABLE IF NOT EXISTS `zsjos_content_review_batch` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `batch_no` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
    `account_id` bigint NOT NULL,
    `operator_user_id` bigint NOT NULL,
    `director_user_id` bigint DEFAULT NULL COMMENT '提交时冻结的责任编导',
    `relation_snapshot_json` json DEFAULT NULL COMMENT '提交时冻结的编导运营关系',
    `context_snapshot_json` json DEFAULT NULL COMMENT '提交时冻结的账号、模板和审核配置',
    `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'DRAFT/DIRECTOR_REVIEW/FINAL_REVIEW/COMPLETED/REJECTED',
    `current_stage` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
    `process_definition_id` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `process_definition_key` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `process_definition_version` int DEFAULT NULL,
    `process_instance_id` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `business_key` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `last_event_key` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `submitted_at` datetime DEFAULT NULL,
    `director_completed_at` datetime DEFAULT NULL,
    `final_completed_at` datetime DEFAULT NULL,
    `finalized_at` datetime DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_content_review_batch_no` (`tenant_id`,`batch_no`,`deleted`),
    UNIQUE KEY `uk_content_review_process` (`tenant_id`,`process_instance_id`),
    UNIQUE KEY `uk_content_review_business_key` (`tenant_id`,`business_key`),
    KEY `idx_content_review_list` (`tenant_id`,`status`,`director_user_id`,`id`),
    KEY `idx_content_review_operator` (`tenant_id`,`operator_user_id`,`status`,`id`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产内容批审批次';

  CREATE TABLE IF NOT EXISTS `zsjos_content_review_batch_item` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `batch_id` bigint NOT NULL,
    `content_id` bigint NOT NULL,
    `content_version_id` bigint NOT NULL,
    `sort_no` int NOT NULL,
    `content_snapshot_json` json NOT NULL,
    `director_decision` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `director_comment` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `director_reviewed_by_user_id` bigint DEFAULT NULL,
    `director_reviewed_at` datetime DEFAULT NULL,
    `final_decision` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `final_comment` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `collect_material` bit(1) NOT NULL DEFAULT b'0',
    `collection_snapshot_json` json DEFAULT NULL COMMENT '终审勾选时冻结的完整素材准备结果',
    `final_reviewed_by_user_id` bigint DEFAULT NULL,
    `final_reviewed_at` datetime DEFAULT NULL,
    `collected_material_id` bigint DEFAULT NULL,
    `collected_material_version_id` bigint DEFAULT NULL,
    `result_status` varchar(24) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `published_platform_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
    `published_at` datetime DEFAULT NULL,
    `published_by_user_id` bigint DEFAULT NULL,
    `version` int NOT NULL DEFAULT 0,
    `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_content_review_item` (`tenant_id`,`batch_id`,`content_version_id`,`deleted`),
    KEY `idx_content_review_item_batch` (`tenant_id`,`batch_id`,`sort_no`,`id`),
    KEY `idx_content_review_item_content` (`tenant_id`,`content_id`,`content_version_id`),
    KEY `idx_content_review_item_version` (`tenant_id`,`content_version_id`,`batch_id`,`deleted`)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生产内容批审条目';

  CREATE TABLE IF NOT EXISTS `zsjos_content_version_file` (
    `id` bigint NOT NULL AUTO_INCREMENT,
