key,value_code,material_version_id","nonUnique":1},{"table":"zsjos_material_field_index","index":"idx_material_field_number","columns":"tenant_id,field_key,number_value,material_version_id","nonUnique":1},{"table":"zsjos_material_field_index","index":"idx_material_field_date","columns":"tenant_id,field_key,date_value,material_version_id","nonUnique":1},{"table":"zsjos_material_field_index","index":"idx_material_field_datetime","columns":"tenant_id,field_key,datetime_value,material_version_id","nonUnique":1},{"table":"zsjos_material_field_index","index":"idx_material_field_version","columns":"tenant_id,material_version_id,field_key,group_index,id","nonUnique":1},{"table":"zsjos_material_file","index":"uk_material_file_ref","columns":"tenant_id,material_version_id,field_key,group_index,infra_file_id,deleted","nonUnique":0},{"table":"zsjos_material_file","index":"idx_material_file_version","columns":"tenant_id,material_version_id,field_key,group_index,id","nonUnique":1},{"table":"zsjos_material_approval_round","index":"uk_material_approval_round","columns":"tenant_id,material_version_id,round_no,deleted","nonUnique":0},{"table":"zsjos_material_approval_round","index":"uk_material_approval_process","columns":"tenant_id,process_instance_id","nonUnique":0},{"table":"zsjos_material_approval_round","index":"idx_material_approval_state","columns":"tenant_id,status,id","nonUnique":1},{"table":"zsjos_material_like","index":"uk_material_like_user","columns":"tenant_id,material_id,user_id","nonUnique":0},{"table":"zsjos_material_like","index":"idx_material_like_active","columns":"tenant_id,user_id,active,material_id","nonUnique":1},{"table":"zsjos_material_favorite","index":"uk_material_favorite_user","columns":"tenant_id,material_id,user_id","nonUnique":0},{"table":"zsjos_material_favorite","index":"idx_material_favorite_active","columns":"tenant_id,user_id,active,material_id","nonUnique":1},{"table":"zsjos_material_reference","index":"uk_material_reference_target","columns":"tenant_id,material_version_id,target_content_version_id","nonUnique":0},{"table":"zsjos_material_reference","index":"uk_material_reference_idempotency","columns":"tenant_id,idempotency_key","nonUnique":0},{"table":"zsjos_material_reference","index":"idx_material_reference_content","columns":"tenant_id,target_content_version_id,id","nonUnique":1},{"table":"zsjos_material_import_batch","index":"uk_material_import_no","columns":"tenant_id,batch_no,deleted","nonUnique":0},{"table":"zsjos_material_import_batch","index":"uk_material_import_idempotency","columns":"tenant_id,idempotency_key,deleted","nonUnique":0},{"table":"zsjos_material_import_batch","index":"idx_material_import_list","columns":"tenant_id,material_type_id,status,id","nonUnique":1},{"table":"zsjos_material_import_error","index":"idx_material_import_error","columns":"tenant_id,batch_id,row_no,id","nonUnique":1},{"table":"zsjos_content_review_config","index":"uk_content_review_config_tenant","columns":"active_tenant_id","nonUnique":0},{"table":"zsjos_content_review_batch","index":"uk_content_review_batch_no","columns":"tenant_id,batch_no,deleted","nonUnique":0},{"table":"zsjos_content_review_batch","index":"uk_content_review_process","columns":"tenant_id,process_instance_id","nonUnique":0},{"table":"zsjos_content_review_batch","index":"uk_content_review_business_key","columns":"tenant_id,business_key","nonUnique":0},{"table":"zsjos_content_review_batch","index":"idx_content_review_list","columns":"tenant_id,status,director_user_id,id","nonUnique":1},{"table":"zsjos_content_review_batch","index":"idx_content_review_operator","columns":"tenant_id,operator_user_id,status,id","nonUnique":1},{"table":"zsjos_content_review_batch_item","index":"uk_content_review_item","columns":"tenant_id,batch_id,content_version_id,deleted","nonUnique":0},{"table":"zsjos_content_review_batch_item","index":"idx_content_review_item_batch","columns":"tenant_id,batch_id,sort_no,id","nonUnique":1},{"table":"zsjos_content_review_batch_item","index":"idx_content_review_item_content","columns":"tenant_id,content_id,content_version_id","nonUnique":1},{"table":"zsjos_content_review_batch_item","index":"idx_content_review_item_version","columns":"tenant_id,content_version_id,batch_id,deleted","nonUnique":1},{"table":"zsjos_content_version_file","index":"uk_content_version_file","columns":"tenant_id,content_version_id,field_key,infra_file_id,deleted","nonUnique":0},{"table":"zsjos_content_version_file","index":"idx_content_version_file_order","columns":"tenant_id,content_version_id,field_key,sort_no,id","nonUnique":1},{"table":"zsjos_partner_invitation","index":"idx_tenant_student_scene_status","columns":"tenant_id,student_person_id,invitation_scene,status,id","nonUnique":1},{"table":"zsjos_partner_invitation","index":"uk_tenant_active_student_invitation","columns":"tenant_id,active_student_person_id","nonUnique":0}]',
      '$[*]' COLUMNS (
        table_name varchar(64) PATH '$.table',
        index_name varchar(64) PATH '$.index',
        column_names varchar(1000) PATH '$.columns',
        non_unique int PATH '$.nonUnique'
      )
    ) expected_index
    LEFT JOIN (
      SELECT table_name,index_name,MIN(non_unique) non_unique,
             GROUP_CONCAT(column_name ORDER BY seq_in_index SEPARATOR ',') column_names
      FROM information_schema.statistics
      WHERE table_schema=DATABASE()
      GROUP BY table_name,index_name
    ) actual_index
      ON actual_index.table_name=expected_index.table_name
     AND actual_index.index_name=expected_index.index_name
    WHERE actual_index.index_name IS NULL
       OR actual_index.non_unique<>expected_index.non_unique
       OR actual_index.column_names<>expected_index.column_names
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 material/content-review indexes are incompatible';
  END IF;
  IF (SELECT COUNT(*) FROM information_schema.columns
      WHERE table_schema=DATABASE() AND table_name='zsjos_content_version'
        AND ((column_name='title_snapshot' AND data_type='varchar' AND character_maximum_length=255)
          OR (column_name='topic_snapshot' AND data_type='varchar' AND character_maximum_length=1000)
          OR (column_name='cover_snapshot_json' AND data_type='json')
          OR (column_name='deliverable_snapshot_json' AND data_type='json')
          OR (column_name='lead_resource_url' AND data_type='varchar' AND character_maximum_length=1024)
          OR (column_name='planned_publish_at' AND data_type='datetime')
          OR (column_name='frozen_at' AND data_type='datetime'))) <> 7
     OR (SELECT COUNT(*) FROM information_schema.columns
         WHERE table_schema=DATABASE() AND table_name='zsjos_partner_invitation'
           AND ((column_name='invitation_scene' AND data_type='varchar' AND character_maximum_length=32
                 AND is_nullable='NO' AND column_default='GENERAL')
             OR (column_name='student_person_id' AND data_type='bigint' AND is_nullable='YES')
             OR (column_name='student_name_snapshot' AND data_type='varchar' AND character_maximum_length=100)
             OR (column_name='student_mobile_snapshot' AND data_type='varchar' AND character_maximum_length=32)
             OR (column_name='initiated_by_director_user_id' AND data_type='bigint')
             OR (column_name='assignment_context_json' AND data_type='json')
             OR (column_name='active_student_person_id' AND data_type='bigint'
                 AND extra LIKE '%STORED GENERATED%')
             OR (column_name='assigned_operator_user_id' AND data_type='bigint' AND is_nullable='YES')
             OR (column_name='assigned_operator_name_snapshot' AND data_type='varchar'
                 AND character_maximum_length=100 AND is_nullable='YES'))) <> 9 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='V191 base-table extensions are incomplete';
  END IF;

  START TRANSACTION;

  INSERT INTO `system_dict_type`
    (`name`,`type`,`status`,`remark`,`creator`,`create_time`,`updater`,`update_time`,`deleted`)
  SELECT seed.name,seed.type,0,'管理员维护；V191 不预置业务选项','V191',NOW(),'V191',NOW(),b'0'
  FROM (
    SELECT '素材适配账号类型' name,'zsjos_material_account_type' type
    UNION ALL SELECT '素材适配专业方向','zsjos_material_profession'
  ) seed
  WHERE NOT EXISTS (SELECT 1 FROM `system_dict_type` existing
                    WHERE existing.type=seed.type AND existing.deleted=b'0');

  INSERT INTO `system_dict_data`
    (`sort`,`label`,`value`,`dict_type`,`status`,`color_type`,`creator`,`create_time`,`updater`,`update_time`,`deleted`)
  SELECT seed.sort,seed.label,seed.value,'zsjos_material_profession',0,'default','V191',NOW(),'V191',NOW(),b'0'
  FROM (
    SELECT 10 sort,'T1 职业营养' label,'t1_occupational_nutrition' value
    UNION ALL SELECT 20,'T2 健康管理','t2_health_management'
    UNION ALL SELECT 30,'T3 心理与社工','t3_psychology_social_work'
    UNION ALL SELECT 40,'T4 药学','t4_pharmacy'
    UNION ALL SELECT 50,'T5 中药学','t5_traditional_chinese_pharmacy'
    UNION ALL SELECT 60,'T6 中医适宜技术','t6_tcm_appropriate_technology'
    UNION ALL SELECT 70,'T7 中医师承专长','t7_tcm_apprenticeship_specialty'
    UNION ALL SELECT 80,'T8 健康医疗学历提升','t8_healthcare_academic_upgrade'
    UNION ALL SELECT 90,'T9 健康职业商业变现','t9_healthcare_career_monetization'
  ) seed
  WHERE NOT EXISTS (SELECT 1 FROM `system_dict_data` existing
                    WHERE existing.dict_type='zsjos_material_profession'
                      AND existing.value=seed.value AND existing.deleted=b'0');

  INSERT INTO `zsjos_material_type`
    (`code`,`name`,`description`,`status`,`allow_manual_create`,`allow_import`,`allow_auto_collect`,
     `recommendation_enabled`,`recommendation_config_json`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
  SELECT seed.code,seed.name,seed.description,0,seed.manual_create,seed.allow_import,seed.auto_collect,
         seed.recommendation_enabled,JSON_OBJECT('dimensions',JSON_ARRAY('account_type','profession','account_stage'),
         'maxResults',20),
         0,'V191',NOW(),'V191',NOW(),b'0',tenant.id
  FROM `system_tenant` tenant
  CROSS JOIN (
    SELECT 'viral_account' code,'爆款账号' name,'爆款账号拆解内容包' description,b'1' manual_create,b'1' allow_import,b'0' auto_collect,b'1' recommendation_enabled
    UNION ALL SELECT 'viral_content','爆款视频/图文','爆款视频或图文拆解内容包',b'1',b'1',b'0',b'1'
    UNION ALL SELECT 'sop','SOP','可检索、可引用的标准作业参考文档',b'1',b'1',b'0',b'0'
    UNION ALL SELECT 'production_content','生产内容','审核通过并明确收录的生产内容',b'0',b'0',b'1',b'1'
  ) seed
  WHERE tenant.deleted=b'0' AND tenant.status=0
    AND NOT EXISTS (SELECT 1 FROM `zsjos_material_type` existing
                    WHERE existing.tenant_id=tenant.id AND existing.code=seed.code AND existing.deleted=b'0');

  INSERT INTO `zsjos_content_review_config`
    (`production_material_type_code`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
  SELECT 'production_content',0,'V191',NOW(),'V191',NOW(),b'0',tenant.id
  FROM `system_tenant` tenant
  WHERE tenant.deleted=b'0' AND tenant.status=0
    AND NOT EXISTS (SELECT 1 FROM `zsjos_content_review_config` existing
                    WHERE existing.tenant_id=tenant.id AND existing.deleted=b'0');

  INSERT INTO `system_menu`
    (`id`,`name`,`permission`,`type`,`sort`,`parent_id`,`path`,`icon`,`component`,`component_name`,
     `workbench_render_mode`,`status`,`visible`,`keep_alive`,`always_show`,`creator`,`create_time`,`updater`,`update_time`,`deleted`)
  SELECT seed.id,seed.name,seed.permission,seed.type,seed.sort,seed.parent_id,seed.path,seed.icon,
         seed.component,seed.component_name,seed.render_mode,0,b'1',b'1',b'1','V191',NOW(),'V191',NOW(),b'0'
  FROM (
    SELECT 80010 id,'素材库' name,'' permission,1 type,60 sort,6735 parent_id,'material-library' path,'ep:collection' icon,'' component,NULL component_name,'native' render_mode
    UNION ALL SELECT 80011,'素材浏览','zsjos:material:query',2,1,80010,'browse','ep:search','zsjos-workbench','MaterialLibraryPage','native'
    UNION ALL SELECT 80012,'素材管理','zsjos:material:manage',2,2,80010,'manage','ep:files','zsjos/material/index','ZsjosMaterial','admin_embed'
    UNION ALL SELECT 80013,'类型与模板','zsjos:material-type:query',2,3,80010,'types','ep:setting','zsjos/materialType/index','ZsjosMaterialType','admin_embed'
    UNION ALL SELECT 80014,'导入记录','zsjos:material-import:query',2,4,80010,'imports','ep:upload-filled','zsjos/materialImport/index','ZsjosMaterialImport','admin_embed'
    UNION ALL SELECT 80015,'内容审核','zsjos:content-review:query',2,5,80010,'content-review','ep:finished','zsjos-workbench','ContentReviewBatchPage','native'
    UNION ALL SELECT 80016,'创建素材','zsjos:material:create',3,1,80011,'','','',NULL,'native'
    UNION ALL SELECT 80017,'修改素材','zsjos:material:update',3,2,80011,'','','',NULL,'native'
    UNION ALL SELECT 80018,'提交素材审批','zsjos:material:submit',3,3,80011,'','','',NULL,'native'
    UNION ALL SELECT 80019,'停用素材','zsjos:material:disable',3,4,80012,'','','',NULL,'admin_only'
    UNION ALL SELECT 80020,'恢复素材','zsjos:material:restore',3,5,80012,'','','',NULL,'admin_only'
    UNION ALL SELECT 80021,'点赞素材','zsjos:material:like',3,6,80011,'','','',NULL,'native'
    UNION ALL SELECT 80022,'收藏素材','zsjos:material:favorite',3,7,80011,'','','',NULL,'native'
    UNION ALL SELECT 80023,'引用素材','zsjos:material:reference',3,8,80011,'','','',NULL,'native'
    UNION ALL SELECT 80024,'创建素材类型','zsjos:material-type:create',3,1,80013,'','','',NULL,'admin_only'
    UNION ALL SELECT 80025,'修改素材类型','zsjos:material-type:update',3,2,80013,'','','',NULL,'admin_only'
    UNION ALL SELECT 80026,'编辑素材模板','zsjos:material-schema:update',3,3,80013,'','','',NULL,'admin_only'
    UNION ALL SELECT 80027,'发布素材模板','zsjos:material-schema:publish',3,4,80013,'','','',NULL,'admin_only'
    UNION ALL SELECT 80028,'下载导入模板','zsjos:material-import:download',3,1,80014,'','','',NULL,'admin_only'
    UNION ALL SELECT 80029,'预检素材导入','zsjos:material-import:preview',3,2,80014,'','','',NULL,'admin_only'
    UNION ALL SELECT 80030,'确认素材导入','zsjos:material-import:commit',3,3,80014,'','','',NULL,'admin_only'
    UNION ALL SELECT 80031,'配置内容审核','zsjos:content-review:config',3,5,80013,'','','',NULL,'admin_only'
    UNION ALL SELECT 80032,'创建审核批次','zsjos:content-review:create',3,1,80015,'','','',NULL,'native'
    UNION ALL SELECT 80033,'提交审核批次','zsjos:content-review:submit',3,2,80015,'','','',NULL,'native'
    UNION ALL SELECT 80034,'编导逐条审核','zsjos:content-review:director-review',3,3,80015,'','','',NULL,'native'
    UNION ALL SELECT 80035,'终审逐条审核','zsjos:content-review:final-review',3,4,80015,'','','',NULL,'native'
    UNION ALL SELECT 80036,'登记发布结果','zsjos:content-review:publish-register',3,5,80015,'','','',NULL,'native'
    UNION ALL SELECT 80037,'学员开通兼职账号','zsjos:partner-invitation:create-student',3,50,7022,'','','',NULL,'native'
    UNION ALL SELECT 80038,'查看全部内容审核','zsjos:content-review:query-all',3,6,80015,'','','',NULL,'native'
    UNION ALL SELECT 80039,'下载导入错误报告','zsjos:material-import:error-download',3,4,80014,'','','',NULL,'admin_only'
    UNION ALL SELECT 80040,'内容生产','zsjos:content:query',2,6,80010,'content-production','ep:edit-pen','zsjos-workbench','ContentProductionPage','native'
  ) seed
  ON DUPLICATE KEY UPDATE
    `name`=VALUES(`name`),`permission`=VALUES(`permission`),`type`=VALUES(`type`),`sort`=VALUES(`sort`),
    `parent_id`=VALUES(`parent_id`),`path`=VALUES(`path`),`icon`=VALUES(`icon`),
    `component`=VALUES(`component`),`component_name`=VALUES(`component_name`),
    `workbench_render_mode`=VALUES(`workbench_render_mode`),`status`=0,`visible`=b'1',
    `keep_alive`=VALUES(`keep_alive`),`always_show`=VALUES(`always_show`),
    `updater`='V191',`update_time`=NOW(),`deleted`=b'0';

  SET v_menu_id=80010;
  WHILE v_menu_id <= 80036 DO
    UPDATE `system_tenant_package`
    SET `menu_ids`=JSON_ARRAY_APPEND(`menu_ids`,'$',v_menu_id),`updater`='V191',`update_time`=NOW()
    WHERE `deleted`=b'0' AND JSON_CONTAINS(`menu_ids`,'6735','$')
      AND NOT JSON_CONTAINS(`menu_ids`,CAST(v_menu_id AS CHAR),'$');
    SET v_menu_id=v_menu_id+1;
  END WHILE;
  UPDATE `system_tenant_package`
  SET `menu_ids`=JSON_ARRAY_APPEND(`menu_ids`,'$',80037),`updater`='V191',`update_time`=NOW()
  WHERE `deleted`=b'0' AND JSON_CONTAINS(`menu_ids`,'7022','$')
    AND NOT JSON_CONTAINS(`menu_ids`,'80037','$');
  UPDATE `system_tenant_package`
  SET `menu_ids`=JSON_ARRAY_APPEND(`menu_ids`,'$',80038),`updater`='V191',`update_time`=NOW()
  WHERE `deleted`=b'0' AND JSON_CONTAINS(`menu_ids`,'6735','$')
    AND NOT JSON_CONTAINS(`menu_ids`,'80038','$');
  UPDATE `system_tenant_package`
  SET `menu_ids`=JSON_ARRAY_APPEND(`menu_ids`,'$',80039),`updater`='V191',`update_time`=NOW()
  WHERE `deleted`=b'0' AND JSON_CONTAINS(`menu_ids`,'6735','$')
    AND NOT JSON_CONTAINS(`menu_ids`,'80039','$');
  UPDATE `system_tenant_package`
  SET `menu_ids`=JSON_ARRAY_APPEND(`menu_ids`,'$',80040),`updater`='V191',`update_time`=NOW()
  WHERE `deleted`=b'0' AND JSON_CONTAINS(`menu_ids`,'6735','$')
    AND NOT JSON_CONTAINS(`menu_ids`,'80040','$');

  -- Preserve access held through the retired standalone content page without inferring role names.
  INSERT INTO `system_role_menu`
    (`role_id`,`menu_id`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
  SELECT DISTINCT role_row.id,target_menu.id,'V191',NOW(),'V191',NOW(),b'0',role_row.tenant_id
  FROM `system_role_menu` source_grant
  JOIN `system_role` role_row ON role_row.id=source_grant.role_id
    AND role_row.tenant_id=source_grant.tenant_id AND role_row.status=0 AND role_row.deleted=b'0'
  CROSS JOIN (SELECT 80010 id UNION ALL SELECT 80040) target_id
  JOIN `system_menu` target_menu ON target_menu.id=target_id.id
    AND target_menu.status=0 AND target_menu.deleted=b'0'
  WHERE source_grant.menu_id=6974 AND source_grant.deleted=b'0'
    AND NOT EXISTS (SELECT 1 FROM `system_role_menu` existing_grant
      WHERE existing_grant.role_id=role_row.id AND existing_grant.menu_id=target_menu.id
        AND existing_grant.tenant_id=role_row.tenant_id AND existing_grant.deleted=b'0');

  INSERT INTO `zsjos_schema_version` (`version`,`description`,`checksum`,`installed_at`)
  VALUES ('V191','Material library, content review, and student partner invitation',
          SHA2('V191__material_library_content_review.sql',256),NOW())
  ON DUPLICATE KEY UPDATE `description`=VALUES(`description`),`checksum`=VALUES(`checksum`);
  INSERT INTO `zsjos_module_schema_version`
    (`module_code`,`version`,`description`,`checksum`,`release_version`,`installed_at`)
  VALUES ('core','V191','Material library, content review, and student partner invitation',
          SHA2('V191__material_library_content_review.sql',256),'baseline',NOW())
  ON DUPLICATE KEY UPDATE `description`=VALUES(`description`),`checksum`=VALUES(`checksum`);

  COMMIT;
END$$
DELIMITER ;

CALL `zsjos_v191_apply`();
DROP PROCEDURE IF EXISTS `zsjos_v191_apply`;
DROP PROCEDURE IF EXISTS `zsjos_v191_add_index`;
DROP PROCEDURE IF EXISTS `zsjos_v191_add_column`;
